        '+': 1,
        '-': 1,
        '*': 2,
        '/': 2
    }

    def evaluate(expression):
        stack = []
        output = []

        for token in expression:
            if token.isdigit():
                output.append(token)
            elif token in precedence:
                while stack and precedence[token] <= precedence[stack[-1]]:
                    output.append(stack.pop())
                stack.append(token)

        while stack:
