                if token == '+':
                    stack.append(operand1 + operand2)
                elif token == '-':
                    stack.append(operand1 - operand2)
                elif token == '*':
                    stack.append(operand1 * operand2)
                elif token == '/':
                    stack.append(operand1 / operand2)

        return stack[0]

    postfix_expression = evaluate(operations)
    result = calculate(postfix_expression)

    return result

